## Вложенные шаги с аккордеоном Вложенные шаги с аккордеоном Шаг может содержать произвольный контент, в том числе другой компонент  `Steps` . Для корректного отображения передайте  `height`  внешним шагам, которые содержат контент с переменной высотой. ```tsx
import React, { useState } from 'react';
import { Steps, Accordion, AccordionItem } from '@salutejs/sdds-finai';

export function App() {
    const [open, setOpen] = useState(false);

    const [innerSteps, setInnerSteps] = useState([{
        indicator: 1,
        title: 'Установка зависимостей',
        status: 'active',
        height: '3.5rem',
    }, {
        indicator: 2,
        title: 'Настройка окружения',
        status: 'inactive',
        height: '3.5rem',
    }, {
        indicator: 3,
        title: 'Запуск проекта',
        status: 'inactive',
    }]);

    const [outerStatuses, setOuterStatuses] = useState([
        { status: 'active' },
        { status: 'inactive' },
        { status: 'inactive' },
    ]);

    const handleInnerChange = (_item, idx, prevIdx) => {
        setInnerSteps(steps => {
            const next = [...steps];
            if (prevIdx !== undefined) {
                next[prevIdx] = { ...next[prevIdx], status: 'completed' };
            }
            next[idx] = { ...next[idx], status: 'active' };
            return next;
        });
    };

    const handleOuterChange = (_item, idx, prevIdx) => {
        setOuterStatuses(statuses => {
            const next = statuses.map(s => ({ ...s }));
            if (prevIdx !== undefined) {
                next[prevIdx] = { ...next[prevIdx], status: 'completed' };
            }
            next[idx] = { ...next[idx], status: 'active' };
            return next;
        });

        if (idx === 1) {
            setOpen(v => !v);
        }
    };

    const outerItems = [{
        indicator: 1,
        title: 'Подготовка',
        height: '4rem',
        ...outerStatuses[0],
    }, {
        indicator: 2,
        height: open ? '16rem' : '7rem',
        content: (
            <Accordion size="h4" view="clear" stretching="filled">
                <AccordionItem
                    title="Шаги установки"
                    type="arrow"
                    opened={open}
                    onClick={() => setOpen(v => !v)}
                    style={{ marginTop: '-10px' }}
                >
                    <Steps
                        orientation="vertical"
                        size="s"
                        hasLine
                        items={innerSteps}
                        onChange={handleInnerChange}
                    />
                </AccordionItem>
            </Accordion>
        ),
        ...outerStatuses[1],
    }, {
        indicator: 3,
        title: 'Проверка',
        ...outerStatuses[2],
    }];

    return (
        <section style={{ width: '400px' }}>
            <Steps orientation="vertical" hasLine items={outerItems} onChange={handleOuterChange} />
        </section>
    );
}
```

